from pathlib import Path
root=Path(__file__).resolve().parents[1]
def edit(name,changes):
 p=root/name;s=p.read_text(encoding='utf-8-sig')
 for a,b in changes:
  if a not in s:raise Exception(name+': '+a[:100])
  s=s.replace(a,b)
 p.write_text(s,encoding='utf-8')
